/**
 * next-routes·project-status·stuck-loading을 Rust로 옮기면서(ADR-191 3단계 3h) 정한 벡터. 기대값은 옮기기 전 TS가 낸 글자(JSON.stringify, 키 순서 포함)다.
 * `intended`가 붙은 벡터만 의도한 차이다: 그 벡터의 기대값은 새 동작이고 옛 TS는 이 벡터에서 실패한다.
 *  - 경로 이름 정렬: 옛 TS는 `localeCompare`(ICU), 지금은 UTF-16 코드 단위 순서다. 대소문자·한글·é·기호가 섞이면 상한 안에 드는 페이지와 skipped의 순서가 달라진다.
 *  - `sampleParams`는 자기 속성만 읽는다(`[constructor]` 폴더를 함수 글자로 채우지 않는다).
 *  - 요구사항 상태 이름이 `constructor`·`__proto__` 같은 `Object.prototype` 속성 이름이어도 다른 상태와 똑같이 센다.
 * 경계를 밟는 벡터: 상한(`routes.length < limit`)의 limit-1·limit·limit+1, `Math.max(1, …)`·`Math.min(…, AUTO_PAGE_MAX)`(0·음수·소수·NaN·Infinity·10·11),
 * 거리 0/1/음수/소수/NaN, 이름 목록 8개와 9개, 로딩 문구 `\.{0,3}`의 3개와 4개, 본문 길이 60과 61, 증거 합 0과 1.
 */

type RouteVector = { name: string; fn: 'changed' | 'candidates'; args: unknown[]; expected: string; intended?: string };
type StatusVector = { name: string; input: Record<string, unknown>; expected: string; intended?: string };
type StuckVector = { name: string; text: string; evidence: Record<string, unknown> | undefined; expected: string };
type IdVector = { name: string; expected: boolean };

function outcome(fn: () => unknown): string {
  try {
    const value = fn();
    return value === undefined ? 'undefined' : JSON.stringify(value);
  } catch {
    return 'THROW';
  }
}

