describe('벡터: 게이트 경로 고르기(next-routes)', () => {
  for (const vector of ROUTE_VECTORS) {
    it(vector.name, () => {
      const [first, servicePath, sampleParams, maxPages, fallbackValue] = vector.args as [never, string, Record<string, string>, number | undefined, string | undefined];
      const actual = outcome(() =>
        vector.fn === 'changed' ? routesFromChangedFiles(first, servicePath, sampleParams, maxPages, fallbackValue) : routesFromCandidates(first, servicePath, sampleParams, maxPages, fallbackValue),
      );
      expect(actual).toBe(vector.expected);
    });
  }

  it('id류 세그먼트 이름', () => {
    for (const vector of ID_VECTORS) expect(isIdLikeSegment(vector.name), JSON.stringify(vector.name)).toBe(vector.expected);
  });

  it('벡터가 경계를 실제로 밟는다: 상한에 걸린 것과 안 걸린 것, 거리 종류, 의도한 차이가 모두 있다', () => {
    const results = ROUTE_VECTORS.map((vector) => JSON.parse(vector.expected) as { routes: unknown[]; skipped: Array<{ reason: string }> });
    expect(results.some((r) => r.skipped.some((s) => s.reason.includes('상한(')))).toBe(true);
    expect(results.some((r) => r.skipped.some((s) => s.reason.includes('외 1개')))).toBe(true);
    expect(results.some((r) => r.skipped.some((s) => s.reason.includes('상한(NaN개)')))).toBe(true);
    expect(results.some((r) => r.skipped.some((s) => s.reason.includes('변경으로 찾은 페이지')))).toBe(true);
    expect(results.filter((r) => r.routes.length === 5).length).toBeGreaterThan(0);
    expect(ROUTE_VECTORS.filter((v) => v.intended !== undefined).length).toBeGreaterThanOrEqual(10);
  });
});

describe('벡터: 현황 집계(project-status)', () => {
  for (const vector of STATUS_VECTORS) {
    it(vector.name, () => {
      expect(outcome(() => buildProjectStatus(vector.input as unknown as ProjectStatusInput))).toBe(vector.expected);
    });
  }
});

describe('벡터: 로딩 멈춤 판정(stuck-loading)', () => {
  for (const vector of STUCK_VECTORS) {
    it(vector.name, () => {
      expect(outcome(() => detectStuckLoading(vector.text, vector.evidence as StuckLoadingEvidence | undefined))).toBe(vector.expected);
    });
  }

  it('벡터가 참과 거짓을 모두 낸다', () => {
    const stuck = STUCK_VECTORS.filter((v) => v.expected !== 'undefined').length;
    expect(stuck).toBeGreaterThan(40);
    expect(STUCK_VECTORS.length - stuck).toBeGreaterThan(40);
  });
});
